			archiveSha256: text(identityCheck.measuredSha256, 'pigallery2 archive digest'),
			license: text(licenseAtPin.spdx, 'pigallery2 license'),
			licenseSha256: text(licenseAtPin.sha256, 'pigallery2 license digest'),
