		boundary.state !== 'unsupported' ||
		boundary.condition !== ANGULAR_PRE_IVY_SUPPORT_BOUNDARY.condition ||
		boundary.instanceEvidence.libraries !== 3 ||
		boundary.instanceEvidence.importSites !== 6
	)
